{'role': 'user', 'content': [{'tool_use_id': 'toolu_01QfuzCWsqxk1RgmUB8R5Yq6', 'type': 'tool_result', 'content': '     1→// === Core Types ===
     2→
     3→export interface ArtifactRecord {
     4→  path: string; // relative to project root
     5→  name: string; // filename without extension
     6→  type: ArtifactType; // derived from path and frontmatter
     7→  status: string; // from frontmatter, e.g. "DRAFT", "APPROVED", "parse-error"
     8→  supersedes: string | null;
     9→  superseded_by: string | null;
    10→  lastModified: string; // ISO 8601
    11→  frontmatter: Record<string, unknown>; // full parsed frontmatter
    12→}
    13→
    14→export type ArtifactType =
    15→  | "spec"
    16→  | "plan"
    17→  | "tasks"
    18→  | "session-summary"
    19→  | "handoff-packet"
    20→  | "validator-verdict"
    21→  | "qa-verdict"
    22→  | "research-request"
    23→  | "research-findings"
    24→  | "orchestrator-state"
    25→  | "unknown";
    26→
    27→export interface LaunchPackage {
    28→  role: string;
    29→  roleDescription: string; // plain-language description
    30→  dispatchMode: string; // "DIRECT" or "ORCHESTRATOR"
    31→  filesToLoad: LaunchFile[];
    32→  startupPrompt: string; // content of the startup prompt
    33→  expectedOutput: string; // expected output artifact path
    34→  completionChecklist: string[];
    35→  terminalCommand: string; // assembled CLI command
    36→}
    37→
    38→export interface LaunchFile {
    39→  path: string; // relative to project root
    40→  purpose: string; // why this file is included
    41→  missing: boolean; // true if file doesn't exist on disk
    42→}
    43→
    44→export interface NextAction {
    45→  role: string;
    46→  reason: string; // plain-language explanation
    47→  launchPackageUrl: string; // link to GET the launch package
    48→}
    49→
    50→export interface DecisionItem {
    51→  id: string; // deterministic hash of source + line
    52→  marker: "[DECISION NEEDED]" | "[ASK OPERATOR]";
    53→  question: string; // extracted question text
    54→  sourceFile: string; // relative path
    55→  lineNumber: number;
    56→  context: string; // surrounding lines for clarity
    57→}
    58→
    59→export interface ProjectConfig {
    60→  projectPath: string;
    61→  projectName: string;
    62→  compatible: boolean;
    63→  missing: string[]; // missing required files
    64→}
    65→
    66→export interface Settings {
    67→  projectPath: string | null;
    68→  anthropicApiKey: string | null;
    69→}
    70→
    71→// === SSE Event Types ===
    72→
    73→export type RoleStatus = "idle" | "launched" | "awaiting-output" | "complete";
    74→
    75→export type SSEEvent =
    76→  | { type: "artifact-changed"; data: ArtifactRecord }
    77→  | { type: "artifact-removed"; data: { path: string } }
    78→  | { type: "status-update"; data: { role: string; status: RoleStatus } }
    79→  | { type: "decision-found"; data: DecisionItem }
    80→  | { type: "connected"; data: { projectPath: string } };
    81→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01BNSTPdPYSTLbUfx1vHowPG', 'type': 'tool_result', 'content': '     1→import Database from "better-sqlite3";
     2→import path from "path";
     3→import fs from "fs";
     4→
     5→// .tinyshop/tinyshop.db lives relative to the Tinyshop app root (process.cwd())
     6→const DB_DIR = path.join(process.cwd(), ".tinyshop");
     7→const DB_PATH = path.join(DB_DIR, "tinyshop.db");
     8→
     9→let db: Database.Database | null = null;
    10→
    11→export function getDb(): Database.Database {
    12→  if (db) return db;
    13→
    14→  fs.mkdirSync(DB_DIR, { recursive: true });
    15→  db = new Database(DB_PATH);
    16→  db.pragma("journal_mode = WAL");
    17→
    18→  db.exec(`
    19→    CREATE TABLE IF NOT EXISTS settings (
    20→      key TEXT PRIMARY KEY,
    21→      value TEXT NOT NULL,
    22→      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    23→    );
    24→  `);
    25→
    26→  return db;
    27→}
    28→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01QpF7veAV5Sr5PqsPYHq3Bq', 'type': 'tool_result', 'content': '     1→import { getDb } from "./db";
     2→import type { Settings } from "@/types/index";
     3→
     4→function getSetting(key: string): string | null {
     5→  const db = getDb();
     6→  const row = db
     7→    .prepare("SELECT value FROM settings WHERE key = ?")
     8→    .get(key) as { value: string } | undefined;
     9→  return row?.value ?? null;
    10→}
    11→
    12→function setSetting(key: string, value: string): void {
    13→  const db = getDb();
    14→  db.prepare(
    15→    `INSERT INTO settings (key, value, updated_at)
    16→     VALUES (?, ?, datetime('now'))
    17→     ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`
    18→  ).run(key, value);
    19→}
    20→
    21→function deleteSetting(key: string): void {
    22→  const db = getDb();
    23→  db.prepare("DELETE FROM settings WHERE key = ?").run(key);
    24→}
    25→
    26→/**
    27→ * Returns the current application settings.
    28→ * Both fields are null if not yet configured.
    29→ */
    30→export function getSettings(): Settings {
    31→  return {
    32→    projectPath: getSetting("projectPath"),
    33→    anthropicApiKey: getSetting("anthropicApiKey"),
    34→  };
    35→}
    36→
    37→/**
    38→ * Merges the provided partial settings into the persisted values.
    39→ * Pass null for a field to clear it. Returns the full updated settings.
    40→ */
    41→export function updateSettings(partial: Partial<Settings>): Settings {
    42→  if ("projectPath" in partial) {
    43→    if (partial.projectPath === null) {
    44→      deleteSetting("projectPath");
    45→    } else {
    46→      setSetting("projectPath", partial.projectPath!);
    47→    }
    48→  }
    49→
    50→  if ("anthropicApiKey" in partial) {
    51→    if (partial.anthropicApiKey === null) {
    52→      deleteSetting("anthropicApiKey");
    53→    } else {
    54→      setSetting("anthropicApiKey", partial.anthropicApiKey!);
    55→    }
    56→  }
    57→
    58→  return getSettings();
    59→}
    60→'}]}
